// The generated contract files (prd-zen-user-widgets-v2 UWA4, UWA9, TUWA4,
// TUWA5, TUWA10, UWB28).
//
// The Rust freshness test (`k2_core::contract::gen`) renders every output
// again, but CI runs only `cargo check` until the contract step lands
// everywhere, so this vitest twin checks the same thing from the other side:
// `contract-snapshot.json` (written by contract-gen) records the sha256 of
// the catalog, the runtime and every output. A catalog edit without a
// regenerate, or a hand edit of a generated file, fails here.
import { createHash } from 'node:crypto'
import { existsSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { CATALOG_ERROR_CODES, type Catalog } from './catalog-types'
import { K2_CAPS, USER_WIDGET_CAPS } from '../k2-caps.generated'
import { ZEN_CATALOG_VERSION, ZEN_CUSTOM_VERBS, ZEN_VERBS } from '../zen/zen-verbs.generated'

const ROOT = resolve(__dirname, '../../../..')
const REGEN = 'run `cargo run -p k2-core --bin contract-gen`'

const sha = (text: string): string => createHash('sha256').update(text, 'utf8').digest('hex')
const read = (rel: string): string => readFileSync(resolve(ROOT, rel), 'utf8')

interface Snapshot {
  catalogVersion: number
  catalogSha256: string
  runtimeSha256: string | null
  files: Record<string, string>
}

const snapshot = JSON.parse(read('sdk/generated/contract-snapshot.json')) as Snapshot
const catalogText = read('crates/k2-core/src/contract/catalog.json')
const catalog = JSON.parse(catalogText) as Catalog

/** The snapshot keys of blocks inside cli/k2, and each one's begin marker. */
const CLI_BLOCKS: Record<string, string> = {
  'cli/k2': '# >>> generated by contract-gen: zen guide api',
  'cli/k2#study app-api': '# >>> generated by contract-gen: study app-api',
}

/** A fenced block in cli/k2, markers included (as contract-gen splices it). */
function cliBlock(cli: string, marker: string): string {
  const begin = cli.indexOf(marker)
  expect(begin, `cli/k2 has no '${marker}' block; ${REGEN}`).toBeGreaterThanOrEqual(0)
  const rest = cli.slice(begin)
  const end = rest.indexOf('# <<< generated')
  expect(end, 'cli/k2 block has no end marker').toBeGreaterThan(0)
  const nl = rest.indexOf('\n', end)
  return rest.slice(0, nl === -1 ? rest.length : nl + 1)
}

describe('TUWA4 twin: generated files match the catalog', () => {
  it('the snapshot was written from this catalog', () => {
    expect(sha(catalogText), `catalog.json changed since the last generate; ${REGEN}`).toBe(snapshot.catalogSha256)
    expect(snapshot.catalogVersion).toBe(catalog.catalogVersion)
    expect(ZEN_CATALOG_VERSION).toBe(catalog.catalogVersion)
  })

  it('the runtime the frame script joined is the one on disk', () => {
    const p = resolve(ROOT, 'sdk/k2-runtime.js')
    const now = existsSync(p) ? sha(readFileSync(p, 'utf8')) : null
    expect(now, `sdk/k2-runtime.js changed since the last generate; ${REGEN}`).toBe(snapshot.runtimeSha256)
  })

  it('every output is as generated', () => {
    const paths = Object.keys(snapshot.files).sort()
    expect(paths).toEqual(
      [
        'cli/k2',
        'cli/k2#study app-api',
        'crates/k2-core/src/app_surface.rs',
        'sdk/generated/k2-frame.js',
        'sdk/generated/k2.d.ts',
        'sdk/server/src/generated/verbs.ts',
        'src/renderer/lib/k2-caps.generated.ts',
        'src/renderer/lib/zen/zen-verbs.generated.ts',
      ].sort(),
    )
    for (const rel of paths) {
      const marker = CLI_BLOCKS[rel]
      const text = marker === undefined ? read(rel) : cliBlock(read('cli/k2'), marker)
      expect(sha(text), `${rel} differs from what contract-gen wrote; ${REGEN}`).toBe(snapshot.files[rel])
    }
  })

  it('the frame script stays under 40 KB (UWA5, raised for Garden data, then the 0.46.1 SDK and its App rows, then catalog v20)', () => {
    expect(Buffer.byteLength(read('sdk/generated/k2-frame.js'), 'utf8')).toBeLessThanOrEqual(40 * 1024)
  })
})

