      'window.startDrag': { cap: null, reach: 'local', kind: 'call' },
      // Catalog v20 (0.46.3 r10): collapsible columns, frame-only like the canvas.
      'layout.get': { cap: null, reach: 'local', kind: 'call' },
      'layout.set': { cap: null, reach: 'local', kind: 'call' },
